//
// Windows-specific implementation of the `spawnSync` function for creating
// child processes and capturing their output. This code is designed to work
// with the Windows API and is not portable to other platforms. It uses pipes
// to redirect the standard output and error streams of the child process back
// to the parent process, allowing the parent to read the output and error
// messages generated by the child process.
//
// The `spawnSync` function takes a command and a list of arguments, creates a
// child process to execute the command, and returns a `ProcessResult` structure
// containing the exit status and the captured output and error messages.
//

#include "child_process.h"

#include <strsafe.h>
#include <windows.h>
#include <cassert>
#include <cstdio>
#include <utility>
#include "string_utils.h"

#ifndef VerifyElseExit
#define VerifyElseExit(condition)                                              \
  do {                                                                         \
    if (!(condition)) {                                                        \
      ExitOnError(#condition);                                                 \
    }                                                                          \
  } while (false)
#endif

namespace node_api_tests {

namespace {

std::string ReadFromPipe(HANDLE pipeHandle);
void ExitOnError(const char* message);

struct AutoHandle {
  HANDLE handle{NULL};

  AutoHandle() = default;
  AutoHandle(HANDLE handle) : handle(handle) {}
  ~AutoHandle() { ::CloseHandle(handle); }

  AutoHandle(const AutoHandle&) = delete;
  AutoHandle& operator=(const AutoHandle&) = delete;

  void Close() {
    ::CloseHandle(handle);
    handle = NULL;
  }
};
}  // namespace

// Create a child process that uses the previously created pipes for STDIN and
// STDOUT.
ProcessResult SpawnSync(std::string_view command,
                        std::vector<std::string> args) {
  return SpawnSync(command, std::move(args), 60 * 1000);
}

ProcessResult SpawnSync(std::string_view command,
                        std::vector<std::string> args,
                        uint32_t timeout_ms) {
  ProcessResult result{};

  // Own the whole process tree, including descendants inheriting pipe handles.
  AutoHandle job(::CreateJobObjectW(nullptr, nullptr));
  VerifyElseExit(job.handle != NULL);
  JOBOBJECT_EXTENDED_LIMIT_INFORMATION limits{};
  limits.BasicLimitInformation.LimitFlags = JOB_OBJECT_LIMIT_KILL_ON_JOB_CLOSE;
  VerifyElseExit(::SetInformationJobObject(
      job.handle, JobObjectExtendedLimitInformation, &limits, sizeof(limits)));

  // Set the bInheritHandle flag so pipe handles are inherited.

  SECURITY_ATTRIBUTES handles_are_inheritable = {
      sizeof(SECURITY_ATTRIBUTES), nullptr, TRUE};

  AutoHandle out_read_handle, out_write_handle;
  VerifyElseExit(CreatePipe(&out_read_handle.handle,
                            &out_write_handle.handle,
                            &handles_are_inheritable,
                            0));
  // Ensure the read handle to the pipe for STDOUT is not inherited.
  VerifyElseExit(
      SetHandleInformation(out_read_handle.handle, HANDLE_FLAG_INHERIT, 0));

  AutoHandle err_read_handle, err_write_handle;
  VerifyElseExit(CreatePipe(&err_read_handle.handle,
                            &err_write_handle.handle,
                            &handles_are_inheritable,
                            0));
  // Ensure the read handle to the pipe for STDERR is not inherited.
  VerifyElseExit(
      SetHandleInformation(err_read_handle.handle, HANDLE_FLAG_INHERIT, 0));

  // Set up members of the STARTUPINFO structure.
  // This structure specifies the STDIN and STDOUT handles for redirection.
  STARTUPINFOA startup_info{};
  startup_info.cb = sizeof(STARTUPINFOA);
  startup_info.dwFlags |= STARTF_USESTDHANDLES;
  startup_info.hStdInput = ::GetStdHandle(STD_INPUT_HANDLE);
  startup_info.hStdOutput = out_write_handle.handle;
  startup_info.hStdError = err_write_handle.handle;

  // Create the child process.

  std::string commandLine = std::string(command);
  for (std::string& arg : args) {
    commandLine += " " + arg;
  }
  PROCESS_INFORMATION process_info{};
  VerifyElseExit(
      CreateProcessA(nullptr,
                     const_cast<char*>(commandLine.c_str()),  // command line
                     nullptr,  // process security attributes
                     nullptr,  // primary thread security attributes
                     TRUE,     // handles are inherited
                     CREATE_DEFAULT_ERROR_MODE | CREATE_SUSPENDED,
                     nullptr,          // use parent's environment
                     nullptr,          // use parent's current directory
                     &startup_info,    // STARTUPINFO pointer
                     &process_info));  // receives PROCESS_INFORMATION
  AutoHandle process(process_info.hProcess), thread(process_info.hThread);
  // Assign before running any child code, so no descendant can escape the job.
  if (!::AssignProcessToJobObject(job.handle, process.handle)) {
    const DWORD error = ::GetLastError();
    // The suspended child is not in the job yet; do not strand it on failure.
    const BOOL terminated = ::TerminateProcess(process.handle, error);
    VerifyElseExit(terminated ||
                   (::GetLastError() == ERROR_ACCESS_DENIED &&
                    ::WaitForSingleObject(process.handle, 0) == WAIT_OBJECT_0));
    ::SetLastError(error);
    ExitOnError("AssignProcessToJobObject");
  }
  VerifyElseExit(::ResumeThread(thread.handle) != static_cast<DWORD>(-1));

  // Bound the wait so a hung test child cannot hang the entire test suite.
  DWORD wait_result = ::WaitForSingleObject(process.handle, timeout_ms);
  if (wait_result == WAIT_TIMEOUT) {
    result.timed_out = true;
    const BOOL terminated = ::TerminateJobObject(job.handle, ERROR_TIMEOUT);
    // The process may exit between the timed wait and termination.
    VerifyElseExit(terminated ||
                   (::GetLastError() == ERROR_ACCESS_DENIED &&
                    ::WaitForSingleObject(process.handle, 0) == WAIT_OBJECT_0));
    wait_result = ::WaitForSingleObject(process.handle, 5000);
  }
  VerifyElseExit(wait_result == WAIT_OBJECT_0);

  DWORD exit_code;
  VerifyElseExit(::GetExitCodeProcess(process.handle, &exit_code));

  // Close before reading: even an exited child may leave descendants holding
  // the write ends open. KILL_ON_JOB_CLOSE also covers the normal-exit path.
  job.Close();

  // Close handles to the stdin and stdout pipes no longer needed by the child
  // process. If they are not explicitly closed, there is no way to recognize
  // that the child process has ended.

  out_write_handle.Close();
  err_write_handle.Close();

  result.status = exit_code;
  result.std_output =
      ReplaceAll(ReadFromPipe(out_read_handle.handle), "\r\n", "\n");
  result.std_error =
      ReplaceAll(ReadFromPipe(err_read_handle.handle), "\r\n", "\n");

  if (result.timed_out) {
    result.std_error += "Child process timed out after " +
                        std::to_string(timeout_ms) + " milliseconds\n";
  }
  return result;
}

namespace {
std::string ReadFromPipe(HANDLE pipeHandle) {
  std::string result;
  constexpr size_t bufferSize = 4096;
  char buffer[bufferSize];

  for (;;) {
    DWORD bytesRead;
    BOOL isSuccess =
        ::ReadFile(pipeHandle, buffer, bufferSize, &bytesRead, nullptr);
    if (!isSuccess || bytesRead == 0) break;

    result.append(buffer, bytesRead);
  }

  return result;
}

// Report a readable error to stderr, never a modal dialog, then exit.
void ExitOnError(const char* message) {
  LPVOID lpMsgBuf;
  LPVOID lpDisplayBuf;
  DWORD dw = GetLastError();

  ::FormatMessageA(FORMAT_MESSAGE_ALLOCATE_BUFFER | FORMAT_MESSAGE_FROM_SYSTEM |
                       FORMAT_MESSAGE_IGNORE_INSERTS,
                   nullptr,
                   dw,
                   MAKELANGID(LANG_NEUTRAL, SUBLANG_DEFAULT),
                   (LPSTR)&lpMsgBuf,
                   0,
                   nullptr);

  lpDisplayBuf = (LPVOID)LocalAlloc(
      LMEM_ZEROINIT, (lstrlenA((LPCSTR)lpMsgBuf) + lstrlenA(message) + 40));
  ::StringCchPrintfA((LPSTR)lpDisplayBuf,
                     LocalSize(lpDisplayBuf),
                     "%s failed with error %d: %s",
                     message,
                     dw,
                     lpMsgBuf);
  fprintf(stderr, "%s\n", (const char*)lpDisplayBuf);

  ::LocalFree(lpMsgBuf);
  ::LocalFree(lpDisplayBuf);
  ::ExitProcess(1);
}

}  // namespace
}  // namespace node_api_tests